const SAVE_PATH := "user://savegame.json"

var world: World
var current_room: Room
var inventory: Array[String] = []

@onready var room_title: Label = $MarginContainer/VBoxContainer/RoomTitle
@onready var room_description: Label = $MarginContainer/VBoxContainer/RoomDescription
@onready var exits_container: HBoxContainer = $MarginContainer/VBoxContainer/ExitsContainer
@onready var items_container: HBoxContainer = $MarginContainer/VBoxContainer/ItemsContainer
@onready var inventory_label: Label = $MarginContainer/VBoxContainer/InventoryLabel
@onready var message_label: Label = $MarginContainer/VBoxContainer/MessageLabel
@onready var save_button: Button = $MarginContainer/VBoxContainer/SaveLoadContainer/SaveButton
@onready var load_button: Button = $MarginContainer/VBoxContainer/SaveLoadContainer/LoadButton


func _ready() -> void:
	save_button.pressed.connect(_on_save_pressed)
	load_button.pressed.connect(_on_load_pressed)

	world = World.new()
	var success := world.load_file("res://adventure.json")
	if not success:
		message_label.text = "Errore nel caricamento: %s" % world.last_error
		return

	current_room = world.get_start_room()
	_update_inventory_ui()
	_update_room_ui()


func _update_room_ui() -> void:
	if current_room == null:
		return

	room_title.text = current_room.name
	room_description.text = current_room.description

	# Svuota i pulsanti precedenti
	for child in exits_container.get_children():
		exits_container.remove_child(child)
		child.queue_free()

	for child in items_container.get_children():
		items_container.remove_child(child)
		child.queue_free()

	# Se la stanza e terminale, mostra la vittoria e non crea uscite
	if current_room.is_end:
		message_label.text = "Complimenti! Hai raggiunto la fine dell'avventura!"
		return

	# Crea un pulsante per ogni uscita disponibile
	for dir in current_room.exits:
		var btn := Button.new()
		btn.text = dir
		btn.pressed.connect(_on_exit_pressed.bind(dir))
		exits_container.add_child(btn)

	# Crea un pulsante per ogni oggetto presente nella stanza
	for item in current_room.items:
		var btn := Button.new()
		btn.text = item
		btn.pressed.connect(_on_item_pressed.bind(item))
		items_container.add_child(btn)


func _update_inventory_ui() -> void:
	if inventory.is_empty():
		inventory_label.text = "Inventario: (vuoto)"
	else:
		var text := "Inventario: "
		for i in range(inventory.size()):
			text += inventory[i]
			if i < inventory.size() - 1:
				text += ", "
		inventory_label.text = text


func _on_exit_pressed(dir: String) -> void:
	if current_room == null:
		return

	# Controllo uscita bloccata
	if current_room.locked_exits.has(dir):
		var required_item: String = current_room.locked_exits[dir]
		if not inventory.has(required_item):
			message_label.text = "L'uscita verso '%s' e bloccata! Ti serve: %s." % [dir, required_item]
			return
		# Sblocca l'uscita in modo permanente
		current_room.locked_exits.erase(dir)

	var next_id: String = current_room.exits.get(dir, "")
	var next_room := world.get_room(next_id)
	if next_room != null:
		current_room = next_room
		message_label.text = ""
		_update_room_ui()


func _on_item_pressed(item: String) -> void:
	if current_room == null:
		return

	if current_room.items.has(item):
		current_room.items.erase(item)
		inventory.append(item)
		message_label.text = "Hai raccolto: %s." % item
		_update_inventory_ui()
		_update_room_ui()


func save_game(path: String = SAVE_PATH) -> bool:
	if current_room == null:
		return false

	var rooms_data: Dictionary = {}
	for room_id in world.rooms:
		var room: Room = world.rooms[room_id]
		rooms_data[room_id] = {
			"items": room.items.duplicate(),
			"locked_exits": room.locked_exits.duplicate()
		}

	var data: Dictionary = {
		"current_room_id": current_room.id,
		"inventory": inventory.duplicate(),
		"rooms": rooms_data
	}

	var file := FileAccess.open(path, FileAccess.WRITE)
	if file == null:
		message_label.text = "Errore durante il salvataggio."
		return false

	file.store_string(JSON.stringify(data, "\t"))
	file.close()

	message_label.text = "Partita salvata."
	return true


func load_game(path: String = SAVE_PATH) -> bool:
	if not FileAccess.file_exists(path):
		message_label.text = "Nessun salvataggio trovato."
		return false

	var file := FileAccess.open(path, FileAccess.READ)
	if file == null:
		message_label.text = "Impossibile aprire il file di salvataggio."
		return false

	var content := file.get_as_text()
	file.close()

	var parsed = JSON.parse_string(content)
	if not (parsed is Dictionary):
		message_label.text = "File di salvataggio non valido."
		return false

	var data: Dictionary = parsed
	if not data.has("current_room_id") or not data.has("inventory") or not data.has("rooms"):
		message_label.text = "Dati di salvataggio incompleti."
		return false

	# Ricarica il mondo base per ripristinare nomi, descrizioni e collegamenti
	if not world.load_file("res://adventure.json"):
		message_label.text = "Errore nel caricamento del mondo."
		return false

	# Ripristina lo stato modificato di ciascuna stanza
	var rooms_data: Dictionary = data["rooms"]
	for room_id in rooms_data:
		var r_state = rooms_data[room_id]
		if not (r_state is Dictionary):
			continue
		var room := world.get_room(str(room_id))
		if room != null:
			if r_state.has("items") and r_state["items"] is Array:
				var items_list: Array[String] = []
				for item in r_state["items"]:
					items_list.append(str(item))
				room.items = items_list
			if r_state.has("locked_exits") and r_state["locked_exits"] is Dictionary:
				room.locked_exits = r_state["locked_exits"].duplicate()

	# Ripristina l'inventario
	var new_inv: Array[String] = []
	for item in data["inventory"]:
		new_inv.append(str(item))
	inventory = new_inv

	# Ripristina la stanza corrente
	var target_room := world.get_room(str(data["current_room_id"]))
	if target_room != null:
		current_room = target_room

	message_label.text = "Partita caricata."
	_update_inventory_ui()
	_update_room_ui()
	return true


func _on_save_pressed() -> void:
	save_game()


func _on_load_pressed() -> void:
	load_game()
